#!/usr/bin/env node
// test-engine-artifact.mjs — proves the DEPLOYED build engine is the same program as its readable source
// (BL-0204). The artifact (plugin/templates/shared/.claude/engines/pandacorp-build.js) is generated by
// generate-engine.mjs from plugin/runtime/engine/pandacorp-build.src.js because Claude Code's Workflow
// tool refuses a script over 524288 bytes. Four independent oracles:
//   1. SIZE      — the artifact stays under a 450 KB budget (headroom below the 512 KB hard limit).
//   2. FRESHNESS — the committed artifact is byte-identical to generate-engine(source).
//   3. AST       — a real parser (acorn, from mission-control's installed deps) gives source and artifact
//                  identical ASTs (positions aside): no token, string, template chunk or regex changed.
//   4. BEHAVIOR  — the whole scenario suites run against the ARTIFACT, and a sabotaged artifact goes RED
//                  (negative control: the harness really executes the file it is pointed at).
// Plus tokenizer unit cases for the constructs a naive comment stripper gets wrong.
// Exit 0 green / 1 red. Output ends in `RESULT: N passed, M failed`.
import { spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { compactEngine, ENGINE_ARTIFACT, ENGINE_SOURCE, tokenize, WORKFLOW_SCRIPT_LIMIT } from "./generate-engine.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, "..", "..");
const SIZE_BUDGET = 450 * 1000;

let passed = 0;
let failed = 0;
function check(ok, name, detail = "") {
  if (ok) { passed++; console.log(`PASS  ${name}`); }
  else { failed++; console.log(`FAIL  ${name}${detail ? `\n      ✗ ${detail}` : ""}`); }
}

const source = readFileSync(path.join(ROOT, ENGINE_SOURCE), "utf8");
const artifact = readFileSync(path.join(ROOT, ENGINE_ARTIFACT), "utf8");
const artifactBytes = Buffer.byteLength(artifact);

// ── 1. Size ──────────────────────────────────────────────────────────────────
check(artifactBytes <= SIZE_BUDGET, `artifact is ${artifactBytes} bytes, within the ${SIZE_BUDGET}-byte budget (Workflow hard limit ${WORKFLOW_SCRIPT_LIMIT})`,
  `artifact is ${artifactBytes} bytes > ${SIZE_BUDGET}: trim prose in ${ENGINE_SOURCE} before it reaches the Workflow limit`);

// ── 2. Freshness ─────────────────────────────────────────────────────────────
check(compactEngine(source) === artifact, "committed artifact == generate-engine(source)", `run node plugin/scripts/generate-engine.mjs`);
check(artifact.startsWith("export const meta = {"), "artifact BEGINS with the pure meta literal (Workflow contract)");
check(/^\/\/ GENERATED from plugin\/runtime\/engine\/pandacorp-build\.src\.js .*do not edit/m.test(artifact), "artifact carries the GENERATED banner");

// ── 3. AST equivalence through an independent parser ─────────────────────────
const mcPackage = path.join(ROOT, "mission-control/package.json");
let acorn = null;
try { acorn = createRequire(mcPackage)("acorn"); } catch {
  try {
    const pnpmAcorn = path.join(ROOT, "mission-control/node_modules/.pnpm/node_modules/acorn");
    if (existsSync(pnpmAcorn)) acorn = createRequire(path.join(pnpmAcorn, "package.json"))("acorn");
  } catch { acorn = null; }
}
if (!acorn) {
  check(false, "acorn resolvable for the AST oracle", "acorn not found under mission-control/node_modules — run pnpm install in mission-control (fail-closed: no AST proof, no pass)");
} else {
  const opts = { ecmaVersion: "latest", sourceType: "module", allowAwaitOutsideFunction: true, allowReturnOutsideFunction: true };
  const withoutPositions = (key, value) => (key === "start" || key === "end" ? undefined : value);
  const astOf = (code) => JSON.stringify(acorn.parse(code, opts), withoutPositions);
  const sourceAst = astOf(source);
  check(sourceAst === astOf(artifact), "source and artifact parse to IDENTICAL ASTs (acorn)");
  const literalValues = (code) => {
    const out = [];
    acorn.parse(code, { ...opts, onToken: (t) => { if (["template", "string", "regexp"].includes(t.type.label)) out.push(code.slice(t.start, t.end)); } });
    return out;
  };
  const a = literalValues(source);
  const b = literalValues(artifact);
  check(a.length > 1000 && a.length === b.length && a.every((v, i) => v === b[i]), `all ${a.length} string/template/regex literals are byte-identical (raw source text)`);
  // Negative control for the oracle itself: a one-character change inside a template literal must be caught.
  const tampered = artifact.replace("FATAL: args.stateCli must be", "FATAL: args.stateCli must  be");
  check(tampered !== artifact && astOf(tampered) !== sourceAst, "AST oracle detects whitespace changed INSIDE a string (negative control)");
}

// ── Tokenizer unit cases ─────────────────────────────────────────────────────
const meta = "export const meta = { name: 'x' }\n";
const cases = [
  ["template keeps comment markers and indentation", `${meta}const a = \`line 1\n    // not a comment\n    /* nor this */ \${b /* real */}\`\n`, "`line 1\n    // not a comment\n    /* nor this */ ${b }`"],
  ["nested template inside a substitution", `${meta}const q = (v) => \`'\${String(v).replaceAll("'", \`'"'"'\`)}'\` // tail\n`, "const q = (v) => `'${String(v).replaceAll(\"'\", `'\"'\"'`)}'`"],
  ["regex with slashes and a class is kept", `${meta}const r = /[/]\\/\\/x/g.test(s) // c\n`, "const r = /[/]\\/\\/x/g.test(s)"],
  ["strings with comment markers are kept", `${meta}const s = '// no' + "/* no */"\n`, "const s = '// no' + \"/* no */\""],
  ["division is not a regex", `${meta}const d = a / b / c\n`, "const d = a / b / c"],
  ["a newline inside a removed block comment still ends the line (ASI)", `${meta}let x = 1 /* a\nb */ let y = 2\n`, "let x = 1\nlet y = 2"],
];
for (const [name, input, expected] of cases) {
  let out = "";
  try { out = compactEngine(input); } catch (e) { out = `THREW ${e.message}`; }
  check(out.includes(expected), `tokenizer: ${name}`, `expected ${JSON.stringify(expected)} in ${JSON.stringify(out)}`);
}
let threw = false;
try { compactEngine("const a = 1\nexport const meta = {}\n"); } catch { threw = true; }
check(threw, "a source that does not begin with `export const meta` is refused");
threw = false;
try { tokenize("const a = `open"); } catch { threw = true; }
check(threw, "an unterminated template literal fails loud");

// ── 4. Behavior: the scenario suites execute the ARTIFACT ────────────────────
function runSuite(script, env) {
  const r = spawnSync(process.execPath, [path.join(HERE, script)], { encoding: "utf8", env: { ...process.env, ...env }, maxBuffer: 64 * 1024 * 1024 });
  const out = `${r.stdout || ""}${r.stderr || ""}`;
  const m = out.match(/RESULT: (\d+) passed, (\d+) failed/);
  return { code: r.status, out, passedCount: m ? Number(m[1]) : -1, failedCount: m ? Number(m[2]) : -1 };
}
const full = runSuite("test-pandacorp-build.mjs", { PANDACORP_ENGINE_RUN: "artifact" });
check(full.code === 0 && full.failedCount === 0 && full.passedCount >= 300 && full.out.includes("ENGINE UNDER TEST: generated artifact"),
  `test-pandacorp-build.mjs: all ${full.passedCount} scenarios GREEN against the artifact`, full.out.split("\n").filter((l) => /FAIL|RESULT|FATAL/.test(l)).slice(0, 10).join(" | "));
const split = runSuite("test-build-engine.mjs", { PANDACORP_ENGINE_RUN: "artifact" });
check(split.code === 0 && split.failedCount === 0 && split.passedCount >= 3, `test-build-engine.mjs: all ${split.passedCount} scenarios GREEN against the artifact`);

const scratch = mkdtempSync(path.join(os.tmpdir(), "engine-artifact-"));
try {
  const sabotaged = path.join(scratch, "pandacorp-build.js");
  const broken = artifact.replace("label: 'baseline-precheck'", "label: 'baseline-precheck-SABOTAGED'");
  writeFileSync(sabotaged, broken);
  const red = runSuite("test-pandacorp-build.mjs", { PANDACORP_ENGINE_RUN: "artifact", PANDACORP_ENGINE_ARTIFACT: sabotaged });
  check(broken !== artifact && red.code !== 0 && red.failedCount > 0, `negative control: a sabotaged artifact goes RED (${red.failedCount} scenarios failed)`);
} finally {
  rmSync(scratch, { recursive: true, force: true });
}

console.log(`RESULT: ${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);
